mapper.select:
select tis.id, tis.task_id, tis.task_name, tis.task_instance_id, ti.engine_type, tis.task_type, tis.cluster_metadata, tis.task_mode, tis.task_status, tis.task_metadata, tis.cluster_id, tis.cluster_type, tis.cluster_metadata, tis.retry_count, tis.root_instance_id, tis.parent_instance_id, tis.retry_scheduled, tis.schedule_id, tis.schedule_name, tis.schedule_instance_name, tis.launch_time, tis.create_time, tis.update_time, ci.cluster_name from task_instance tis left join task_info ti on tis.task_id = ti.id left join cluster_info ci on ci.id = tis.cluster_id
tis.is_deleted = 0
and tis.task_name like CONCAT('%', #{params.taskName}, '%')
and ti.engine_type = #{params.engineType}
and ci.cluster_name like CONCAT('%', #{params.clusterName}, '%')
and tis.task_mode = #{params.taskMode}
and tis.cluster_type = #{params.clusterType}
order by tis.create_time desc
